/* Browser application. Content is generated from content/research.json, never from private notes. */
(function(){'use strict';
const D=window.ResearchContent,C=window.StudyCore,$=id=>document.getElementById(id),E=C.escape;
if(!D){$('main').textContent='Learning content is missing. Keep content/content.js beside this project, then reload.';return;}
C.checkContent(D);
const linkScience=C.glossaryLinker(D.terms);
const storage=(()=>{try{return window.localStorage;}catch{return {getItem(){return null;},setItem(){throw Error('Storage unavailable');}};}})();
let recoveryRaw=null;try{const raw=storage.getItem(C.KEY);if(raw)try{C.validState(JSON.parse(raw));}catch{recoveryRaw=raw;}}catch{}
let state=C.load(storage),route='',termStack=[],termContext=null,review={index:0,revealed:false,filter:'all',dueOnly:false},quiz={index:0,filter:'all',kind:'all',difficulty:'all',missed:false,reveal:false},viewer={slide:1,zoom:100},sourceSection=0;
let visualLibraryPosition=null;
let timer=null,timerStarted=0,timerElapsed=0,noticeTimer;
const objectives=D.objectives,classes=[...new Set(objectives.map(o=>o.group))],objectiveOf=id=>objectives.find(o=>o.lessons.includes(id)),groups=[...new Set(D.topics.map(t=>t.group))],topic=id=>D.topics.find(t=>t.id===id),term=id=>D.terms.find(t=>t.id===id);
function persist(){if(recoveryRaw!==null){notice('Unreadable saved data has been preserved. Export recovery data before importing a valid backup.');return false;}try{C.save(storage,state);return true;}catch{notice('Changes are in memory only. Browser storage is unavailable or full; export a backup.');return false;}}
function notice(s){$('status').textContent=s;$('status').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('status').classList.remove('visible'),5500);}
function opt(value,label,selected){return `<option value="${E(value)}"${value===selected?' selected':''}>${E(label)}</option>`;}
function picker(selected='all',id='topic-picker',includeAll=true){return `<select id="${id}" class="topic-select" aria-label="Filter by learning objective">${opt('all','All objectives',selected)}${topic(selected)?opt(selected,'Current lesson: '+topic(selected).title,selected):''}${classes.map(g=>`<optgroup label="${E(g)}">${objectives.filter(o=>o.group===g).map(o=>opt('objective:'+o.id,'Objective '+o.number+': '+o.title,selected)).join('')}</optgroup>`).join('')}</select>`;}
function matchesObjective(topicId,filter){return filter==='all'||topicId===filter||(filter.startsWith('objective:')&&objectives.find(o=>o.id===filter.slice(10))?.lessons.includes(topicId));}
function objectivePicker(topicId='',id='objective-picker'){
const current=objectiveOf(topicId);return `<select id="${id}" class="topic-select" aria-label="Choose a learning objective"><option value="">Choose a learning objective…</option>${classes.map(g=>`<optgroup label="${E(g)}">${objectives.filter(o=>o.group===g).map(o=>opt(o.id,'Objective '+o.number+': '+o.title,current?.id)).join('')}</optgroup>`).join('')}</select>`;}
function provenance(source){return `<p class="source">Manuscript: ${E(source)}</p>`;}
function detail(title,body,open=false){return `<details${open?' open':''}><summary>${E(title)}</summary>${body}</details>`;}
function table(headers,rows,caption=''){return `<div class="table-scroll"><table>${caption?`<caption>${E(caption)}</caption>`:''}<thead><tr>${headers.map(h=>`<th scope="col">${E(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row">${E(c)}</th>`:`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function termButton(id){const t=term(id);return t?`<button class="term" data-term="${id}">${E(t.term)}</button>`:'';}
function topicLink(t){return `<a href="#lesson/${t.id}">${E(t.title)}</a>`;}
function endReview(){return '<div class="end-review"><button data-action="end-review" class="quiet">End review</button><p class="tiny muted">Return to the overview. Your answers and notes stay saved.</p></div>';}
function goto(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function setupNav(){const nav=[['home','Overview'],['path','Learning objectives'],['map','Concept explorer'],['glossary','Glossary'],['flashcards','Flashcards'],['questions','Practice questions'],['compare','Compare concepts'],['visuals','Figures and tables'],['presentation','Presentation practice'],['appraisal','Critical appraisal'],['notes','Bookmarks and notes'],['sources','Original sources'],['guide','User Guide'],['about','About the Developer']];
$('navigation').innerHTML=nav.slice(0,2).map(([h,l])=>`<a href="#${h}"${route.split('/')[0]===h?' aria-current="page"':''}>${l}</a>`).join('')+classes.map(g=>`<details${route.startsWith('lesson/')&&objectiveOf(route.split('/')[1])?.group===g?' open':''}><summary>${E(g)}</summary>${objectives.filter(o=>o.group===g).map(o=>`<a href="#objective/${o.id}"${route.startsWith('lesson/')&&objectiveOf(route.split('/')[1])?.id===o.id?' aria-current="page"':''}>Objective ${o.number}: ${E(o.title)}</a>`).join('')}</details>`).join('')+nav.slice(2).map(([h,l])=>`<a href="#${h}"${route.split('/')[0]===h?' aria-current="page"':''}>${l}</a>`).join('');}
function home(){const r=C.readiness(D,state),due=C.dueCards(D.flashcards,state.ratings),recent=state.recent.map(topic).filter(Boolean).slice(0,3),next=D.topics.find(t=>!state.read.includes(t.id))||D.topics[0];return `<p class="eyebrow">Personal research workspace</p><h1>Chromosome 9 Study Desk</h1><p class="lead">Understand the evidence. Explain the study.</p><p class="study-title muted">${E(D.studyTitle)}</p><div class="toolbar"><button data-action="quick-guide" class="primary">Quick guide</button><button data-action="share">Share app</button><button data-action="copy-link">Copy link</button></div><section class="surface"><label for="objective-picker"><strong>Choose your learning objective</strong></label><p class="tiny muted">Selecting an objective opens its first lesson immediately.</p>${objectivePicker()}<p class="tags">6 learning objectives · 15 lessons · 7 manuscript figures · 2 manuscript tables</p><a class="button" href="#visuals">View methodology, figures and tables</a></section><div class="ribbon"><strong>Start with the study design</strong><p>Six runs represent four BioSamples. The three ALL runs measure one REH source.</p>${topicLink(D.topics[1])}</div>${detail('Your study activity',`<p class="metric">${r.studied} of ${r.total} topics marked read · ${r.correct} of ${r.answered} answered questions correct</p><p>${due.length} cards are new or due. <a href="#flashcards">Open recall practice</a>.</p><p>Suggested next topic: ${topicLink(next)}</p>${recent.length?`<p>Recently opened: ${recent.map(topicLink).join(' · ')}</p>`:''}<p class="tiny muted">${E(r.interpretation)}</p>`)}${detail('How this workspace uses your materials','<p>The manuscript is the scientific authority. Oral slides guide rehearsal, and the poster guides concise explanation. Learning objectives are inferred from manuscript sections. Plain-language explanations and memory aids are labelled educational interpretations.</p><p>Your private notes and progress stay in this browser. No accounts, paid services or AI API calls are required.</p><a href="#appraisal">Review source reconciliation</a>')}<footer>Study content is source-linked. It is not a diagnostic or clinical decision tool.</footer>`;}
function visualConnection(id){return D.visualConnections.find(v=>v.id===id);}
function connectionLinks(id){const v=visualConnection(id);return `<p class="objective-context"><strong>Connected objectives:</strong> ${v.objectives.map(id=>{const o=objectives.find(o=>o.id===id);return `<a href="#objective/${o.id}">Objective ${o.number} · ${E(o.title)}</a>`;}).join(' · ')}</p><p>${E(v.purpose)}</p>`;}
function visualLink(v){return `<li><a href="#visuals/${v.id}">${E(v.title)}</a> — ${E(v.purpose)}</li>`;}
function objectiveEvidence(o){const list=o.id==='o6'?D.visualConnections:D.visualConnections.filter(v=>v.objectives.includes(o.id));return `<section class="surface objective-evidence"><h2>Visual evidence for Objective ${o.number}</h2><p>${o.id==='o6'?'Use these source visuals to appraise methods and results. This objective synthesizes their limitations; it has no separate original figure.':'These methodology diagrams, figures and tables support this learning objective.'}</p><ul>${list.map(visualLink).join('')}</ul></section>`;}
function groupedVisuals(){return objectives.map(o=>{const list=D.visualConnections.filter(v=>v.objectives[0]===o.id);const supporting=D.visualConnections.filter(v=>v.objectives[0]!==o.id&&v.objectives.includes(o.id));return `<section class="objective-visual-group" aria-label="Visuals for Objective ${o.number}"><h2>Objective ${o.number} · ${E(o.title)}</h2><a href="#objective/${o.id}">Open this objective</a>${list.map(v=>v.id==='method'?methodVisual():v.id.startsWith('table')?inlineTable(Number(v.id.slice(-1))-1):inlineFigure(D.figures.find(f=>f.id===v.id))).join('')}${supporting.length?`<p>Also supports this objective:</p><ul>${supporting.map(visualLink).join('')}</ul>`:''}${o.id==='o6'?'<p>Appraise the methodology and all result visuals above. No separate original figure is supplied for the limitations and conclusions.</p><a href="#lesson/limitations">Connect the evidence to its limitations</a>':''}</section>`;}).join('');}
function figureTeaching(f){const x=f.teaching;return `<div class="visual-explanation"><p><strong>What this shows:</strong> ${E(x.shows)}</p>${detail('How to read it',`<p>${E(x.read)}</p>`)}${detail('Walk through this figure',`<p>${E(x.walkthrough)}</p>`)}${detail('Why it matters',`<p>${E(x.why)}</p>`)}${detail('Remember it in seconds',`<p>${E(x.remember)}</p>`)}<p class="tiny muted">Newly written teaching explanation of the supplied figure, not additional study findings.</p></div>`;}
function tableTeaching(index){return `<div class="visual-explanation"><p><strong>How to read this table:</strong> ${index===0?'Each row is one sequencing run. Move across to connect its accession, BioSample, biological material and platform. Compare BioSample identifiers before treating rows as independent biological sources.':'Each row is an annotation category; the next two columns compare AML-associated and ALL-associated summaries. Gene labels, codon-number labels and coding-sequence-position labels are different units and must not be combined.'}</p>${detail('Why it matters',`<p>${index===0?'The three ALL runs share SAMN13831871 while using different platforms. This makes the table essential for understanding why run counts do not equal participant counts.':'Codon and coding-position labels depend on transcript context. A matching number across pooled genes does not establish the same genomic site or a mutational hotspot.'}</p>`)}${detail('Try explaining it yourself',`<p>${index===0?'Find ALL-1, ALL-2 and ALL-3. Which identifier stays the same, and which platform labels change?':'Choose a row and state its unit before comparing the two columns. What extra transcript or allele information would you need to interpret an exact variant?'}</p>`)}</div>`;}
function methodVisual(){return `<figure class="lesson-visual"><figcaption><strong>Methodology · from public records to descriptive results</strong></figcaption>${connectionLinks('method')}<ol class="method-flow"><li><strong>Public sequencing runs</strong><span>Six runs · four BioSamples · AML and ALL-associated material</span></li><li><strong>Quality control and trimming</strong><span>FastQC and Trimmomatic · reported Q30 and minimum 50 bp</span></li><li><strong>Assembly and assessment</strong><span>SPAdes and QUAST · minimum contig length 500 bp</span></li><li><strong>Chromosome 9 alignment</strong><span>Geneious · GRCh38.p14 / NC_000009.12 · inspect identity and coverage</span></li><li><strong>Calling and annotation</strong><span>Reported calling filters · reference-based annotation context</span></li><li><strong>Descriptive comparisons</strong><span>Counts, genes, coding labels, overlap and clustering</span></li></ol><p>New teaching schematic based on manuscript §3.1. It summarizes the reported workflow; it is not an original manuscript figure or a reconstruction of undocumented settings.</p>${detail('How to follow the arrows','<p>Read from top to bottom. Each stage prepares information for the next: quality control checks reads, trimming removes unwanted sequence, assembly combines overlapping sequence, alignment places sequence against chromosome 9, and calling plus annotation produces records for comparison.</p>')}${detail('Why this order matters','<p>Errors and incomplete coverage can propagate through the workflow. A good quality score does not guarantee correct alignment, and an annotation does not validate a clinical effect.</p>')}${detail('Remember the whole method','<p>Retrieve → check → prepare → align → annotate → compare. This is a teaching summary; consult the methods for exact reported tools and filters.</p>')}<a href="#lesson/processing">Read the processing lesson</a></figure>`;}
function inlineFigure(f){return `<figure class="lesson-visual"><figcaption><strong>${E(f.title)}</strong></figcaption>${connectionLinks(f.id)}${f.files.map((src,i)=>`<a href="#visuals/${f.id}" aria-label="Open ${E(f.title)}${f.files.length>1?' panel '+(i+1):''}"><img src="${E(src)}" width="${f.dimensions[i].width}" height="${f.dimensions[i].height}" alt="${E(f.title)}${f.files.length>1?' — panel '+(i+1):''}" loading="lazy"></a>`).join('')}${figureTeaching(f)}<p><strong>Interpretation:</strong> ${E(f.meaning)}</p><p class="tiny muted">${E(f.caution)}</p>${provenance(f.source)}<a class="button" href="#visuals/${f.id}">Enlarge and explore</a></figure>`;}
function inlineTable(index){const rows=D.source.tables[index];return `<section class="lesson-visual">${connectionLinks('table'+(index+1))}${table(rows[0],rows.slice(1),'Manuscript Table '+(index+1)+' · '+(index===0?'Dataset composition':'Selected gene and position labels'))}<p>${index===0?'The three ALL runs share one BioSample. Run counts must not be read as independent patient counts.':'These are selected annotation labels. Pooled coding positions are not chromosome coordinates or validated hotspots.'}</p>${tableTeaching(index)}${provenance('Table '+(index+1))}<a href="#visuals/table${index+1}">Open table on its own</a></section>`;}
function lessonVisuals(t){let html=D.figures.filter(f=>visualConnection(f.id).lessons.includes(t.id)).map(inlineFigure).join('');if(['design','processing'].includes(t.id))html=methodVisual()+html;if(t.id==='provenance')html=inlineTable(0)+html;if(['annotation','positions'].includes(t.id))html+=inlineTable(1);return html?`<section aria-label="Diagrams and tables for this lesson"><h2>See the evidence</h2>${html}</section>`:'';}
function lesson(id){const t=topic(id)||D.topics[0],ix=D.topics.indexOf(t),objective=objectiveOf(t.id),same=objective.lessons.map(topic),within=same.indexOf(t);state.recent=[t.id,...state.recent.filter(x=>x!==t.id)].slice(0,10);state.lastTopic=t.id;persist();return `<p class="eyebrow">${E(objective.group)} · Objective ${objective.number}</p><div class="toolbar">${objectivePicker(t.id)}</div><p class="objective-context"><strong>Objective ${objective.number}:</strong> ${E(objective.title)}</p><article class="lesson"><h1>${E(t.title)}</h1><p class="lead">${E(t.summary)}</p><div class="ribbon"><strong>WHY in seconds</strong><p>${E(t.why)}</p></div><p class="tiny muted">Useful terms</p><div class="inline-list">${t.terms.map(termButton).join('')}</div>${objectiveEvidence(objective)}${lessonVisuals(t)}${detail('Background to understand first',`<p class="tiny muted">Established science, separate from this study’s results. Select an underlined term for its explanation, worked example and source.</p>${t.terms.map(term).filter(x=>x&&x.backgroundSources).slice(0,2).map(x=>`<p><strong>${E(x.term)}:</strong> ${E(x.plain)}</p>`).join('')}`)}${detail('Scientific explanation',`<p>${E(t.detail)}</p>${t.steps.length?'<ol>'+t.steps.map(s=>`<li>${E(s)}</li>`).join('')+'</ol>':''}`)}${detail('Evidence and interpretation',`<p>${E(t.evidence)}</p>${provenance(t.source)}<p class="tiny muted">${E(t.support)}</p><p>Oral slides: ${t.slides.join(', ')}. Poster: ${E(t.poster)}.</p>`)}${detail('A misconception to avoid',`<p>${E(t.misconception)}</p>`)}${detail('Remember it through an example',`<p>${E(t.example)}</p><p class="tiny muted">Examples and analogies are newly written explanations, not extra study results.</p>`)}${detail('Self-check',`<p>Explain this topic in two sentences. What is one conclusion the study cannot establish?</p><a class="button" href="#questions/${t.id}">Practise this topic</a>`)}${detail('Related concepts',`<ul>${t.related.map(id=>`<li>${topicLink(topic(id))}</li>`).join('')}</ul>`)}${detail('Private note and revision',`<label for="lesson-note">My note about this topic</label><textarea maxlength="50000" id="lesson-note" data-note="${t.id}" placeholder="Write in your own words…">${E(state.notes[t.id]||'')}</textarea><p class="tiny muted">Saves as you type in this browser.</p><button data-action="bookmark" data-id="${t.id}" aria-pressed="${state.bookmarks.includes(t.id)}">${state.bookmarks.includes(t.id)?'Remove bookmark':'Bookmark for revision'}</button>`)}<div class="lesson-nav"><button data-action="previous-lesson" data-id="${t.id}"${ix===0?' disabled':''}>Previous</button><span class="lesson-index">Lesson ${within+1} of ${same.length} in Objective ${objective.number}</span><button data-action="next-lesson" data-id="${t.id}"${ix===D.topics.length-1?' disabled':''}>Next</button></div><div class="toolbar"><button class="quiet" data-action="mark-read" data-id="${t.id}" aria-pressed="${state.read.includes(t.id)}">${state.read.includes(t.id)?'Marked read':'Mark this topic read'}</button></div></article>`;}
function path(){return `<p class="eyebrow">Objective-based learning</p><h1>Learning objectives</h1><p>Six learning objectives guide the study sequence. They are derived from the manuscript, rather than claimed as six author-stated research objectives. Selecting an objective opens its first lesson directly.</p>${classes.map(g=>detail(g,`<ol>${objectives.filter(o=>o.group===g).map(o=>`<li><a href="#objective/${o.id}"><strong>Objective ${o.number}:</strong> ${E(o.title)}</a><p class="tiny muted">${o.lessons.length} lesson${o.lessons.length===1?'':'s'} · ${o.lessons.filter(id=>state.read.includes(id)).length} marked read</p></li>`).join('')}</ol>`,true)).join('')}`;}
function conceptMap(){const nodes=['design','provenance','alignment','annotation','counts','coding','positions','overlap','clustering','limitations','conclusions'];const coords={design:[20,25],provenance:[300,25],alignment:[580,25],annotation:[20,130],counts:[300,130],coding:[580,130],positions:[580,235],overlap:[20,235],clustering:[300,235],limitations:[300,340],conclusions:[580,340]};const lines=D.relationships.filter(([a,b])=>coords[a]&&coords[b]).map(([a,b])=>`<line x1="${coords[a][0]+105}" y1="${coords[a][1]+25}" x2="${coords[b][0]+105}" y2="${coords[b][1]+25}"/>`).join('');return `<h1>Concept explorer</h1><p>Relationships come from the study, rather than shared words alone.</p><p class="tiny muted">New explanatory schematic. Lines show connections, not causal effects or numerical distances.</p><div class="map-scroll"><svg class="concept-map" viewBox="0 0 820 420" role="group" aria-label="Study concepts connected through provenance, annotation and interpretation limits">${lines}${nodes.map(id=>{const [x,y]=coords[id];return `<g role="button" tabindex="0" data-concept="${id}" aria-label="Open ${E(topic(id).title)}"><rect x="${x}" y="${y}" width="215" height="55" rx="6"/><text x="${x+10}" y="${y+24}">${E(({design:'Study design',provenance:'Biological provenance',alignment:'Identity and coverage',annotation:'Annotation records',counts:'Count distributions',coding:'Predicted coding effects',positions:'Pooled position labels',overlap:'Set overlap',clustering:'Run-level clustering',limitations:'Interpretation limits',conclusions:'Defensible synthesis'})[id])}</text></g>`;}).join('')}</svg></div>${detail('Read every relationship',`<ul>${D.relationships.map(([a,b,meaning,support])=>`<li>${topicLink(topic(a))} and ${topicLink(topic(b))}: ${E(meaning)} <span class="tiny muted">(${E(support)})</span></li>`).join('')}</ul>`)}${detail('Hierarchical topic explorer',groups.map(g=>`<h3>${E(g)}</h3><ul>${D.topics.filter(t=>t.group===g).map(t=>`<li>${topicLink(t)}</li>`).join('')}</ul>`).join(''))}`;}
function glossary(){return `<h1>Glossary and abbreviations</h1><p>Open a term for its plain meaning and relevance. Details stay out of the way until needed.</p><label for="term-search">Find a term</label><input id="term-search" class="browse-filter" type="search" placeholder="Try coverage, PAX5, BioSample…"><ul class="rows" id="term-list">${D.terms.map(t=>`<li data-filter-text="${E((t.term+' '+t.full).toLowerCase())}">${termButton(t.id)}${t.full?` <span class="tiny muted">${E(t.full)}</span>`:''}</li>`).join('')}</ul><p id="term-empty" class="empty" hidden>No matching term. Try another word.</p>`;}
function openTerm(id,push=true){const t=term(id);if(!t)return;if(!$('term-dialog').open){termContext={scroll:window.scrollY,focus:document.activeElement};termStack=[];}if(push&&termStack.at(-1)!==id)termStack.push(id);$('term-content').innerHTML=`<div class="dialog-head"><div><p class="eyebrow">Glossary</p><h2 id="term-title">${E(t.term)}</h2>${t.full?`<p>${E(t.full)}</p>`:''}</div><button data-action="close-term" class="quiet">Return to ${route.startsWith('visual')?'diagram':route.startsWith('lesson')?'lesson':'reading'}</button></div><p class="lead">${E(t.plain)}</p><strong>What this study says about it</strong><p>${E(t.why)}</p>${t.origin?detail('Meaning of the name',`<p>${E(t.origin)}</p>`):''}${detail('Why does it work this way?',`<p>${E(t.mechanism)}</p>`)}${t.example?detail('Worked example',`<p>${E(t.example)}</p><p class="tiny muted">Teaching example, not an additional study result.</p>`):''}${detail('Remember it this way',`<p>${E(t.remember)}</p>`)}<p class="source">${E(t.support)} Manuscript context: ${E(t.source)}.</p>${t.backgroundSources?`<aside class="surface"><strong>Established background · sources</strong><ul>${t.backgroundSources.map(s=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)}</a></li>`).join('')}</ul><p class="tiny muted">Verified background explains the concept; it does not supply missing study measurements or validate its variants.</p></aside>`:''}<div class="inline-list">${t.related.map(termButton).join('')}</div><div class="toolbar"><button data-action="previous-term"${termStack.length<2?' disabled':''}>Previous term</button><button data-action="term-lesson" data-id="${t.topic}">Open related lesson</button></div>`;$('term-content').innerHTML=linkScience($('term-content').innerHTML,id);if(!$('term-dialog').open)$('term-dialog').showModal();$('term-dialog').scrollTop=0;}
function closeTerm(){const d=$('term-dialog');if(d.open)d.close();if(termContext){const c=termContext;requestAnimationFrame(()=>{window.scrollTo(0,c.scroll);if(c.focus&&c.focus.isConnected)c.focus.focus({preventScroll:true});});}termContext=null;termStack=[];}
function cardQueue(){let list=D.flashcards.filter(c=>matchesObjective(c.topic,review.filter));return review.dueOnly?C.dueCards(list,state.ratings):list;}
function flashcards(){const list=cardQueue();review.index=Math.min(review.index,Math.max(0,list.length-1));const c=list[review.index];return `<p class="eyebrow">Active recall</p><h1>Flashcards</h1><div class="toolbar">${picker(review.filter,'card-filter',true)}<label><input type="checkbox" id="due-only"${review.dueOnly?' checked':''}>New or due only</label></div>${c?`<p class="tiny muted">Card ${review.index+1} of ${list.length}</p><article class="surface"><h2>${E(c.front)}</h2>${review.revealed?`<div class="answer"><p>${E(c.back)}</p>${provenance(c.source)}</div><p>How well did you recall it before revealing?</p><div class="toolbar">${['again','hard','good','easy'].map(g=>`<button data-grade="${g}" data-card="${c.id}">${g[0].toUpperCase()+g.slice(1)}</button>`).join('')}</div>`:`<p>Try answering aloud before opening the explanation.</p><button data-action="reveal-card" class="primary">Reveal answer</button>`}</article><div class="lesson-nav"><button data-action="prev-card"${review.index===0?' disabled':''}>Previous card</button><button data-action="next-card"${review.index>=list.length-1?' disabled':''}>Next card</button></div>`:'<p class="empty">No cards match, or every matching card is scheduled for later. Turn off “New or due only” to practise any time.</p>'}${detail('How scheduling works','<p>This app uses a simple, transparent interval rule, not a validated mastery model. Again schedules 10 minutes; Hard 1 day; Good starts at 3 days; Easy starts at 7 days. Good/Easy double with successive non-Again ratings, capped at 365 days. Again resets the level. New cards are always eligible.</p><p>Changing the computer clock changes what is due. Ratings are self-assessments.</p>')}${endReview()}`;}
function questionQueue(){return D.questions.filter(q=>(matchesObjective(q.topic,quiz.filter))&&(quiz.kind==='all'||q.type===quiz.kind)&&(quiz.difficulty==='all'||q.difficulty===quiz.difficulty)&&(!quiz.missed||state.answers[q.id]?.correct===false));}
function questions(){const list=questionQueue();quiz.index=Math.min(quiz.index,Math.max(0,list.length-1));const q=list[quiz.index],a=q&&state.answers[q.id];return `<p class="eyebrow">Question bank</p><h1>Practise the evidence</h1><div class="toolbar">${picker(quiz.filter,'quiz-filter',true)}<select id="question-kind" aria-label="Question type">${[['all','All types'],['mcq','Multiple choice'],['short','Short answer']].map(([v,l])=>opt(v,l,quiz.kind)).join('')}</select><select id="question-difficulty" aria-label="Question difficulty">${['all','Recall','Conceptual','Critical evaluation'].map(v=>opt(v,v==='all'?'All difficulty levels':v,quiz.difficulty)).join('')}</select><label><input id="missed-only" type="checkbox"${quiz.missed?' checked':''}>Missed questions</label></div>${q?`<p class="tiny muted">Question ${quiz.index+1} of ${list.length} · ${E(q.difficulty)} · ${E(topic(q.topic).title)}</p><article class="surface"><h2>${E(q.prompt)}</h2>${q.type==='mcq'?`<div class="options">${q.options.map((o,i)=>`<button class="option${a&&a.response===String(i)?' selected':''}${a&&i===q.correct?' correct':''}" data-answer="${i}" data-question="${q.id}"${a?' disabled':''}>${String.fromCharCode(65+i)}. ${E(o)}</button>`).join('')}</div>${a?`<div class="answer"><strong>${a.correct?'Correct.':'Review this point.'}</strong><p>${E(q.explanation)}</p>${provenance(q.source)}</div><button data-action="retry-question" data-id="${q.id}">Try again</button>`:''}`:`<label for="short-answer">Your explanation</label><textarea maxlength="50000" id="short-answer" data-question-note="${q.id}">${E(state.notes['draft-'+q.id]??a?.response??'')}</textarea>${quiz.reveal||a?`<div class="answer"><strong>Model answer</strong><p>${E(q.answer)}</p><p>Interpretation to avoid: ${E(q.explanation)}</p>${provenance(q.source)}</div><p class="tiny muted">Compare your answer yourself. No automatic language grading is performed.</p><div class="toolbar"><button data-self-grade="true" data-id="${q.id}">I explained it accurately</button><button data-self-grade="false" data-id="${q.id}">Needs more revision</button></div>${a?`<p class="tiny">Saved self-assessment: ${a.correct?'accurate':'needs revision'}.</p>`:''}`:'<button data-action="reveal-short" class="primary">Compare with model answer</button>'}`}</article><div class="lesson-nav"><button data-action="prev-question"${quiz.index===0?' disabled':''}>Previous question</button><button data-action="next-question"${quiz.index>=list.length-1?' disabled':''}>Next question</button></div>${detail('Question provenance',`<p>Learning objective: ${E(q.objective)}.</p><p>${E(q.support)}</p>${provenance(q.source)}`)}`:'<p class="empty">No questions match this selection. Change a filter or practise some questions first.</p>'}${endReview()}`;}
function compare(){return `<h1>Compare concepts</h1><p>Study the distinctions that most affect interpretation.</p>${D.comparisons.map(c=>detail(c.title,table(c.headers,c.rows)+provenance(c.source))).join('')}`;}
function viewerHTML(images,download='',label='Scientific figure'){return `<section class="viewer" aria-label="${E(label)}"><div class="toolbar"><button data-action="zoom-out" aria-label="Zoom out">−</button><span id="zoom-value">${viewer.zoom}%</span><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="fit-width">Fit width</button><button data-action="fullscreen">Full screen</button>${download?`<a class="button" download href="${E(download)}">Download original</a>`:''}</div><div class="viewer-stage" id="viewer-stage" tabindex="0">${images.map((src,i)=>`<img loading="lazy" src="${E(src)}" alt="${E(label)}${images.length>1?' panel '+String.fromCharCode(65+i):''}"${viewer.zoom!==100?` class="zoomed" style="width:${viewer.zoom}%"`:''}>`).join('')}</div></section>`;}
function visuals(id){if(!id){return `<h1>Figures and tables</h1><p>Methodology and results are shown below. Select a figure to enlarge it. Visuals are grouped by learning objective and also appear in their related lessons.</p>${groupedVisuals()}`;}if(id==='method')return `<a href="#visuals">Back to visual library</a><h1>Methodology workflow</h1>${methodVisual()}`;if(id==='table1'||id==='table2'){const index=id==='table1'?0:1,t=D.source.tables[index];return `<a href="#visuals">Back to visual library</a><h1>${index===0?'Dataset composition':'Selected gene and position labels'}</h1>${connectionLinks(id)}${table(t[0],t.slice(1),'Original manuscript Table '+(index+1))}<p>${index===0?'The three ALL runs share SAMN13831871.':'Position labels are pooled across coding sequences, not chromosome coordinates.'}</p>${tableTeaching(index)}${provenance('Table '+(index+1))}<div class="inline-list">${(index===0?['run','biosample','replicate']:['codon','transcript','hotspot']).map(termButton).join('')}</div>`;}
const f=D.figures.find(f=>f.id===id);if(!f)return '<h1>Figure not found</h1><a href="#visuals">Open the visual library</a>';return `<a href="#visuals">Back to visual library</a><h1>${E(f.title)}</h1>${connectionLinks(f.id)}${viewerHTML(f.files,f.files[0],f.title)}<p class="lead">${E(f.meaning)}</p>${figureTeaching(f)}<div class="ribbon"><strong>Interpretation boundary</strong><p>${E(f.caution)}</p></div><div class="inline-list">${(f.terms||topic(f.topic).terms).map(termButton).join('')}</div><p class="tiny muted">Linked glossary key for the original image. Text embedded inside the image is unchanged.</p>${provenance(f.source)}${detail('Study the surrounding explanation',`<p>${E(topic(f.topic).detail)}</p>${topicLink(topic(f.topic))}`)}`;}
function presentation(){const sl=D.slides[viewer.slide-1]||D.slides[0];return `<p class="eyebrow">Oral explanation and defence</p><h1>Presentation practice</h1><div class="toolbar"><button data-action="prev-slide"${viewer.slide===1?' disabled':''}>Previous slide</button><label for="slide-select">Slide <select id="slide-select">${D.slides.map(s=>opt(String(s.number),s.number+'. '+s.title,String(viewer.slide))).join('')}</select></label><button data-action="next-slide"${viewer.slide===10?' disabled':''}>Next slide</button></div>${viewerHTML([sl.image],'sources/Oral_Presentation.pptx','Oral slide '+sl.number)}<div class="ribbon"><strong>Key message</strong><p>${E(sl.message)}</p></div>${detail('Oral explanation guide',`<p>${E(sl.guide)}</p><p>Practise explaining the point without reading the slide. Use “annotation records” when legacy figure labels say “mutations”.</p>${provenance(sl.source)}`)}${detail('Audience follow-up',`<p>${E(sl.question)}</p><details><summary>Model answer</summary><p>${E(sl.answer)}</p></details><p class="tiny muted">${E(sl.questionKind)}</p>`)}${detail('Rehearsal checklist',`<div class="checklist">${D.rehearsal.map((r,i)=>`<label><input type="checkbox" data-rehearsal="${i}"${state.rehearsal[i]?' checked':''}>${E(r)}</label>`).join('')}</div><div class="toolbar"><button data-action="timer" id="timer-button">${timer?'Pause':'Start'} rehearsal timer</button><span id="timer-value">${Math.floor((timerElapsed+(timer?Date.now()-timerStarted:0))/1000)} seconds</span><button data-action="reset-timer">Reset timer</button></div><p class="tiny muted">The timer is for this session and is not a readiness score.</p>`)}${endReview()}`;}
function appraisal(){return `<h1>Critical appraisal</h1><p>The study’s contribution and its limits belong together. No unsupported evidence-quality score is assigned.</p>${detail('Strengths',`<ul><li>Publicly identifiable run accessions and biological sources.</li><li>A defined chromosome 9 reference.</li><li>Complementary gene, coding, overlap and clustering summaries.</li></ul>${provenance('Discussion')}`,true)}${detail('Interpretation limits',`<p>${E(topic('limitations').detail)}</p>${provenance('Discussion')}`,true)}${detail('Source reconciliation and open questions',D.discrepancies.map(d=>`<h3>${E(d.title)}</h3><p>${E(d.detail)}</p>${provenance(d.source)}`).join(''))}${detail('Content-to-source matrix',table(['Topic','Manuscript','Oral slides','Poster'],D.topics.map(t=>[t.title,t.source,t.slides.join(', '),t.poster])))}${detail('What would improve the evidence?',`<p>${E(topic('conclusions').detail)}</p>${provenance('Discussion; Conclusion')}`)}`;}
function notes(){const marks=state.bookmarks.map(topic).filter(Boolean),saved=Object.entries(state.notes).filter(([id,val])=>val&&topic(id));return `<h1>Bookmarks and private notes</h1><p>Data stays in this browser on this device. Export a backup before clearing browser data or changing addresses.</p><div class="toolbar"><button data-action="export-state" class="primary">Export learning backup</button><label class="button" for="import-state">Import backup</label><input class="sr-only" id="import-state" type="file" accept="application/json,.json"></div><p class="tiny muted">Import replaces your current learning state after validation. Existing notes are not sent to a server.</p>${detail('Bookmarked topics',marks.length?`<ul>${marks.map(t=>`<li>${topicLink(t)}</li>`).join('')}</ul>`:'<p>No bookmarks yet. Open “Private note and revision” inside a lesson.</p>',true)}${detail('Saved notes',saved.length?saved.map(([id,n])=>`<h3>${topicLink(topic(id))}</h3><p style="white-space:pre-wrap">${E(n)}</p>`).join(''):'<p>No lesson notes yet.</p>')}${detail('Missed questions',D.questions.filter(q=>state.answers[q.id]?.correct===false).map(q=>`<p>${E(q.prompt)}</p><a href="#questions/${q.topic}">Revise this topic</a>`).join('')||'<p>No missed questions saved.</p>')}`;}
function manuscriptSections(){const paras=D.source.paragraphs,sections=[{title:'Title, authors and abstract',paragraphs:[]}];for(const p of paras){if((/^\d[\d.]*\s/.test(p)&&p.length<180)||p==='REFERENCES'){sections.push({title:p,paragraphs:[]});}else sections.at(-1).paragraphs.push(p);}return sections;}
function sources(kind=''){if(kind==='oral'){return presentation();}if(kind==='poster')return `<a href="#sources">Back to original sources</a><h1>Scientific poster</h1>${viewerHTML(['assets/poster/poster.png'],'sources/Poster.pptx','FASCON scientific poster')}<p class="tiny muted">Verified image preview of the editable poster. Original 23 × 33 inch canvas; fit proportionally for A1 printing.</p>`;if(kind==='manuscript'){const sections=manuscriptSections(),current=sections[sourceSection]||sections[0];return `<a href="#sources">Back to original sources</a><h1>Manuscript reading view</h1><p class="tiny muted">Readable text extracted from the DOCX, not a rendering of its original page layout. Figures and tables are in the visual library.</p><div class="toolbar"><label for="manuscript-section">Section <select id="manuscript-section">${sections.map((s,i)=>opt(String(i),s.title,String(sourceSection))).join('')}</select></label><a class="button" href="sources/Manuscript.docx" download>Download original Word file</a></div><article class="reading" tabindex="0"><h2>${E(current.title)}</h2>${current.paragraphs.map(p=>`<p>${E(p)}</p>`).join('')}</article>`;}return `<h1>Original sources</h1><p>Keep the original materials alongside the learning content. The manuscript remains the scientific authority.</p><ul class="rows"><li><a href="#sources/manuscript">Read the manuscript text</a> · <a download href="sources/Manuscript.docx">Download DOCX</a></li><li><a href="#presentation">View the ten oral slides</a> · <a download href="sources/Oral_Presentation.pptx">Download PPTX</a></li><li><a href="#sources/poster">View the poster</a> · <a download href="sources/Poster.pptx">Download PPTX</a></li><li><a download href="App_Preferences.md">App preferences used for this build</a></li></ul><p>Slide and poster previews are images. Text and tables remain editable in the downloadable PowerPoint files.</p><a href="#appraisal">Source differences and interpretation cautions</a>`;}
function searchView(q){const hits=C.search(D,q);return `<h1>Search</h1><p>Results for <strong>${E(q)}</strong></p>${hits.length?`<ul class="rows">${hits.map(h=>`<li>${h.kind==='term'?`<button class="term" data-term="${h.id}">${E(h.title)}</button>`:`<a href="#${h.kind==='topic'?'lesson/'+h.id:h.kind==='figure'?'visuals/'+h.id:'question/'+h.id}">${E(h.title)}</a>`}<span class="tiny muted"> · ${E(h.kind)}</span>${provenance(h.source)}</li>`).join('')}</ul>`:'<p>No matches. Use at least two characters and try a simpler term.</p>'}`;}
function guide(){return `<h1>User Guide</h1>${detail('Study a topic','<p>Use the grouped objective dropdown or Learning objectives. Selecting an objective opens its first lesson directly. Each lesson identifies its objective and lesson position. Read the short meaning, then expand scientific details, evidence or misconceptions as needed. Previous and Next start the destination at the top.</p>',true)}${detail('Understand a term','<p>Tap an underlined term. Plain meaning and relevance appear first. Mechanism, memory aid and naming information are separate. Previous term revisits your glossary history; Return restores the same reading position and focus.</p>')}${detail('Recall and practise','<p>Flashcards require a recall attempt before revealing. Ratings schedule future reviews using the documented simple rule. Multiple-choice answers are checked against the source-based answer; short answers require self-assessment. End review returns to the overview without clearing work.</p>')}${detail('View figures and original documents','<p>Choose a visual in Figures and tables. Zoom, fit width and full screen are available where the browser supports them. Full screen is not guaranteed on all mobile browsers. Original Word content is supplied as a text reading view and a download; it is not presented as a faithful DOCX page renderer.</p>')}${detail('Save and restore learning','<p>Notes, bookmarks, read markers, ratings, answers, theme, sidebar preference and rehearsal checklist use localStorage. They persist through refresh on the same address/browser. They do not follow you to another device or a different deployment URL. Timer and current review position are session-only. Clearing site data removes saved progress. Backup export/import is available in Bookmarks and private notes.</p>')}${detail('Share the app address','<p>Copy link copies a clean HTTP(S) app address. Share app uses the native share menu when available, then clipboard or a visible link. Local file addresses are not copied. No production domain is preconfigured; after private or public deployment, sharing uses the actual address. Sending the URL does not export your private learning notes.</p>')}${detail('Source and privacy boundaries','<p>No AI backend, analytics, account or paid API is used. Manuscript content and source files are bundled locally. This delivered project has not been published. Before any public deployment, review the included scientific material and use a private repository when appropriate.</p>')}`;}
function about(){return `<h1>About the Developer</h1><article class="surface profile"><img class="portrait" src="assets/progress-ajayi.jpg" alt="Professional portrait of Progress Ajayi" width="150" height="150"><div><h2>Progress Ajayi</h2><p><strong>Physiologist and bioinformatician</strong></p><p>Progress Ajayi is a physiologist and bioinformatician with a first-class undergraduate qualification in Physiology and a master’s qualification in Human Physiology awarded with distinction. He is pursuing a PhD in Molecular Biology and Genomics.</p><p>Research interests include bioinformatics, clinical and experimental data analysis, research software development, and clear scientific reporting.</p><p><a href="https://www.linkedin.com/in/progress-ajayi" target="_blank" rel="noopener noreferrer">LinkedIn</a> · <a href="mailto:ajayiprogress04@gmail.com">Email</a></p></div></article><p class="tiny muted">Biography and portrait follow the published reference Hub profile inspected on 17 October 2026. The reference’s appendicitis-specific dedication has not been applied to this study.</p><p class="tiny muted">The chromosome icon was created for this app. It is not a conference or institutional mark.</p>`;}
function applyTheme(){document.documentElement.dataset.theme=state.theme;$('theme').value=state.theme;document.body.classList.toggle('collapsed',state.sidebar);$('menu').setAttribute('aria-expanded',String(window.matchMedia('(max-width:680px)').matches?document.body.classList.contains('drawer'):!state.sidebar));}
function render(preserveScroll=false){let incoming;try{incoming=decodeURIComponent(location.hash.slice(1)||'home');}catch{incoming='home';}const routeChanged=incoming!==route;const returningToVisualLibrary=routeChanged&&incoming==='visuals'&&route.startsWith('visuals/')&&visualLibraryPosition!==null;if(routeChanged&&route==='visuals')visualLibraryPosition=window.scrollY;route=incoming;let [view,id]=route.split('/');if(view==='objective'){const o=objectives.find(o=>o.id===id);goto('lesson/'+(o?o.lessons[0]:D.topics[0].id));return 'lesson';}if(view==='question'){const q=D.questions.find(x=>x.id===id);if(q){if(routeChanged){quiz.filter=q.topic;quiz.kind='all';quiz.difficulty='all';quiz.missed=false;quiz.index=questionQueue().findIndex(x=>x.id===q.id);}view='questions';}else view='home';}if(view==='questions'&&id&&topic(id)&&routeChanged){quiz.filter=id;quiz.index=0;quiz.reveal=false;}const handlers={home,path,map:conceptMap,glossary,lesson:()=>lesson(id),flashcards,questions,compare,visuals:()=>visuals(id),presentation,appraisal,notes,sources:()=>sources(id),search:()=>searchView(id||''),guide,about};$('main').innerHTML=(recoveryRaw!==null?'<section class="surface"><strong>Saved data needs recovery</strong><p>Your existing data could not be read and has not been overwritten.</p><button data-action="export-recovery">Export original recovery data</button> <a href="#notes">Import a valid backup</a></section>':'')+(handlers[view]||home)();$('main').innerHTML=linkScience($('main').innerHTML);setupNav();document.body.classList.remove('drawer');$('shade').hidden=true;applyTheme();if(returningToVisualLibrary){$('main').focus({preventScroll:true});window.scrollTo(0,visualLibraryPosition);requestAnimationFrame(()=>window.scrollTo(0,visualLibraryPosition));}else if(!preserveScroll){window.scrollTo(0,0);$('main').focus({preventScroll:true});}return view;}
function refresh(){render(true);}
function updateZoom(){document.querySelectorAll('.viewer-stage img').forEach(im=>{im.style.width=viewer.zoom+'%';im.classList.toggle('zoomed',viewer.zoom!==100);});if($('zoom-value'))$('zoom-value').textContent=viewer.zoom+'%';}
function exportState(){download('Chromosome9_Learning_Backup.json',JSON.stringify(state,null,2),'application/json');}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function sharing(native){const url=C.cleanURL(location,window.STUDY_DESK_PRODUCTION_URL||'');if(!url){notice('Open a hosted or local-server HTTP(S) address first. A private file path is not a shareable app link.');return;}if(native&&navigator.share){try{await navigator.share({title:D.name,text:D.subtitle,url});return;}catch(err){if(err.name==='AbortError')return;}}try{await navigator.clipboard.writeText(url);notice('Clean app link copied. Learning notes are not included.');}catch{$('status').innerHTML='App link: <a href="'+E(url)+'">'+E(url)+'</a>'; $('status').classList.add('visible');} }
async function act(action,el){switch(action){case'quick-guide':$('guide-dialog').showModal();break;case'close-guide':$('guide-dialog').close();break;case'close-term':closeTerm();break;case'previous-term':termStack.pop();openTerm(termStack.at(-1),false);break;case'term-lesson':closeTerm();goto('lesson/'+el.dataset.id);break;case'bookmark':{const id=el.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();el.textContent=state.bookmarks.includes(id)?'Remove bookmark':'Bookmark for revision';el.setAttribute('aria-pressed',String(state.bookmarks.includes(id)));break;}case'mark-read':{const id=el.dataset.id;state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];persist();el.textContent=state.read.includes(id)?'Marked read':'Mark this topic read';el.setAttribute('aria-pressed',String(state.read.includes(id)));break;}case'previous-lesson':case'next-lesson':{const ix=D.topics.findIndex(t=>t.id===el.dataset.id),n=ix+(action==='next-lesson'?1:-1);if(D.topics[n])goto('lesson/'+D.topics[n].id);break;}case'reveal-card':review.revealed=true;refresh();break;case'prev-card':review.index=Math.max(0,review.index-1);review.revealed=false;render();break;case'next-card':review.index++;review.revealed=false;render();break;case'reveal-short':quiz.reveal=true;refresh();break;case'prev-question':quiz.index=Math.max(0,quiz.index-1);quiz.reveal=false;render();break;case'next-question':quiz.index++;quiz.reveal=false;render();break;case'retry-question':delete state.answers[el.dataset.id];persist();refresh();break;case'prev-slide':viewer.slide=Math.max(1,viewer.slide-1);viewer.zoom=100;render();break;case'next-slide':viewer.slide=Math.min(10,viewer.slide+1);viewer.zoom=100;render();break;case'zoom-in':viewer.zoom=Math.min(300,viewer.zoom+25);updateZoom();break;case'zoom-out':viewer.zoom=Math.max(50,viewer.zoom-25);updateZoom();break;case'fit-width':viewer.zoom=100;updateZoom();break;case'fullscreen':try{const stage=$('viewer-stage');if(stage?.requestFullscreen)await stage.requestFullscreen();else notice('Full screen is not available in this browser. Use zoom or download the original.');}catch{notice('Full screen could not open. Use zoom or download instead.');}break;case'end-review':goto('home');break;case'export-state':exportState();break;case'export-recovery':if(recoveryRaw!==null)download('Chromosome9_Recovery_Data.json',recoveryRaw,'application/json');break;case'share':await sharing(true);break;case'copy-link':await sharing(false);break;case'timer':if(timer){timerElapsed+=Date.now()-timerStarted;clearInterval(timer);timer=null;}else{timerStarted=Date.now();timer=setInterval(()=>{if($('timer-value'))$('timer-value').textContent=Math.floor((timerElapsed+Date.now()-timerStarted)/1000)+' seconds';},1000);}refresh();break;case'reset-timer':if(timer)clearInterval(timer);timer=null;timerElapsed=0;refresh();break;}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-term],[data-concept],[data-grade],[data-answer],[data-self-grade]');if(!el)return;if(el.disabled)return;if(el.dataset.term){openTerm(el.dataset.term);return;}if(el.dataset.concept){goto('lesson/'+el.dataset.concept);return;}if(el.dataset.grade){if(!review.revealed)return;const id=el.dataset.card;state.ratings[id]=C.schedule(state.ratings[id],el.dataset.grade);persist();review.revealed=false;if(!review.dueOnly)review.index=Math.min(review.index+1,cardQueue().length-1);refresh();notice('Rating saved. The next review date is based on your chosen interval.');return;}if(el.dataset.answer!==undefined){const q=D.questions.find(q=>q.id===el.dataset.question);state.answers[q.id]={response:el.dataset.answer,correct:Number(el.dataset.answer)===q.correct,at:Date.now()};persist();refresh();return;}if(el.dataset.selfGrade!==undefined){const q=D.questions.find(q=>q.id===el.dataset.id);state.answers[q.id]={response:$('short-answer')?.value||state.notes['draft-'+q.id]||'',correct:el.dataset.selfGrade==='true',at:Date.now(),selfAssessed:true};persist();refresh();return;}if(el.dataset.action)act(el.dataset.action,el).catch(()=>notice('That action could not finish. Your saved work remains available.'));});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.concept){e.preventDefault();goto('lesson/'+e.target.dataset.concept);}if(e.key==='Escape'&&document.body.classList.contains('drawer')){closeDrawer();}});
document.addEventListener('input',e=>{if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;persist();}if(e.target.dataset.questionNote){state.notes['draft-'+e.target.dataset.questionNote]=e.target.value;persist();}if(e.target.id==='term-search'){const q=e.target.value.toLowerCase();let visible=0;document.querySelectorAll('#term-list li').forEach(li=>{li.hidden=!li.dataset.filterText.includes(q);if(!li.hidden)visible++;});$('term-empty').hidden=visible>0;}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='objective-picker'&&el.value){const o=objectives.find(o=>o.id===el.value);if(o)goto('lesson/'+o.lessons[0]);}if(el.id==='topic-picker'&&el.value)goto('lesson/'+el.value);if(el.id==='theme'){state.theme=el.value;persist();applyTheme();}if(el.id==='card-filter'){review.filter=el.value;review.index=0;review.revealed=false;refresh();}if(el.id==='due-only'){review.dueOnly=el.checked;review.index=0;review.revealed=false;refresh();}if(el.id==='quiz-filter'){quiz.filter=el.value;quiz.index=0;quiz.reveal=false;goto('questions');refresh();}if(el.id==='question-kind'){quiz.kind=el.value;quiz.index=0;quiz.reveal=false;refresh();}if(el.id==='question-difficulty'){quiz.difficulty=el.value;quiz.index=0;quiz.reveal=false;refresh();}if(el.id==='missed-only'){quiz.missed=el.checked;quiz.index=0;refresh();}if(el.id==='slide-select'){viewer.slide=Number(el.value);viewer.zoom=100;render();}if(el.id==='manuscript-section'){sourceSection=Number(el.value);render();}if(el.dataset.rehearsal!==undefined){state.rehearsal[el.dataset.rehearsal]=el.checked;persist();}if(el.id==='import-state'&&el.files[0]){try{if(el.files[0].size>3000000)throw Error('Backup is too large.');const incoming=C.validState(JSON.parse(await el.files[0].text()));state=incoming;recoveryRaw=null;const stored=persist();applyTheme();refresh();notice(stored?'Learning backup restored.':'Backup loaded in memory. Export it before closing because browser storage is unavailable.');}catch(err){notice('Backup not imported: '+err.message);}}});
$('search-form').addEventListener('submit',e=>{e.preventDefault();goto('search/'+encodeURIComponent($('search').value.trim()));});
$('menu').addEventListener('click',()=>{if(window.matchMedia('(max-width:680px)').matches){const open=document.body.classList.toggle('drawer');$('shade').hidden=!open;$('menu').setAttribute('aria-expanded',String(open));}else{state.sidebar=!state.sidebar;persist();applyTheme();}});
function closeDrawer(){document.body.classList.remove('drawer');$('shade').hidden=true;$('menu').setAttribute('aria-expanded','false');$('menu').focus();}
$('shade').addEventListener('click',closeDrawer);$('drawer-close').addEventListener('click',closeDrawer);
$('term-dialog').addEventListener('cancel',e=>{e.preventDefault();closeTerm();});
window.addEventListener('hashchange',()=>{if($('term-dialog').open)closeTerm();if($('guide-dialog').open)$('guide-dialog').close();if(!location.hash.startsWith('#questions/'))quiz.reveal=false;render();});
applyTheme();render();
// Exposed only for deterministic simulated-DOM smoke checks; no private data leaves this page.
window.StudyDeskTest={render,openTerm,closeTerm,act,getState:()=>state,getReview:()=>review,getQuiz:()=>quiz,getRoute:()=>route};
})();
